// New pages only: Google results after the date and Venice's cited sources, minus platforms and every link the story already has.
const s = $('Store Settings').first().json;
const story = $('Read Story From Archive').first().json;
const host = (u) => { const m = String(u || '').match(/^https?:\/\/([^\/?#:]+)/i); return m ? m[1].replace(/^www\./, '').toLowerCase() : ''; };
const known = new Set(String(story.known_links || '').split('\n').map(l => l.trim().split(' ')[0]).filter(Boolean));
const seen = new Map();
const add = (url, found_by, gdate) => {
  if (!url || !/^https?:/i.test(url)) return;
  const clean = url.split('#')[0].replace(/[.,;]+$/, ''); const h = host(clean);
  if (!h || s.platform_domains.some(p => h === p || h.endsWith('.' + p)) || known.has(clean) || seen.has(clean)) return;
  seen.set(clean, { url: clean, domain: h, found_by, gdate: gdate || '' });
};
const serper = $('Search Google Since Story (Serper)').all().flatMap(i => (i.json.organic || []).map(r => ({ link: r.link, date: r.date || '' })));
const v = $('Search Web Since Story (Venice)').first().json || {};
const vurls = ((v.venice_parameters || {}).web_search_citations || []).map(c => c.url)
  .concat(((((v.choices || [])[0] || {}).message || {}).content || '').match(/https?:\/\/[^\s)\]>"']+/g) || []);
for (let i = 0; i < Math.max(serper.length, vurls.length); i++) { if (serper[i]) add(serper[i].link, 'serper', serper[i].date); add(vurls[i], 'venice'); }
const list = [...seen.values()].slice(0, s.max_candidates);
// One item per page to read; an empty run still passes one item so the reply is sent.
return list.length ? list.map(c => ({ json: c })) : [{ json: { url: '', domain: '', found_by: 'none' } }];

// Publication date of a page: its metadata, then its address, then Google's date. No date found = unknown (never a guess from the text).
const MON = { jan: 1, feb: 2, mar: 3, apr: 4, may: 5, jun: 6, jul: 7, aug: 8, sep: 9, oct: 10, nov: 11, dec: 12 };
const iso = (y, m, d) => { const t = new Date(Date.UTC(+y, +m - 1, +d)); return +y > 1990 && t.getUTCMonth() === +m - 1 && t.getUTCDate() === +d && t.getTime() < Date.now() + 2 * 864e5 ? t.toISOString().slice(0, 10) : ''; };
const dateIn = (s, rel) => { s = String(s || ''); let m;
  if ((m = s.match(/\b(20\d\d)[-\/.](\d{1,2})[-\/.](\d{1,2})/))) return iso(m[1], m[2], m[3]);
  if ((m = s.match(/\b(\d{1,2})(?:st|nd|rd|th)?\s+(jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)[a-z]*\.?,?\s+(20\d\d)\b/i))) return iso(m[3], MON[m[2].toLowerCase()], m[1]);
  if ((m = s.match(/\b(jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)[a-z]*\.?\s+(\d{1,2})(?:st|nd|rd|th)?,?\s+(20\d\d)\b/i))) return iso(m[3], MON[m[1].toLowerCase()], m[2]);
  if (rel && (m = s.match(/\b(\d+)\s+(minute|hour|day|week|month)s?\s+ago\b/i))) return new Date(Date.now() - m[1] * { minute: 6e4, hour: 36e5, day: 864e5, week: 6048e5, month: 2592e6 }[m[2].toLowerCase()]).toISOString().slice(0, 10);
  return ''; };
const META = /(?:article:published_time|og:published_time|datePublished|date_published|publish[-_]?date|citation_publication_date|citation_date|dc\.date(?:\.issued)?|parsely-pub-date|sailthru\.date|pubdate)["']?\s*(?:content\s*=|:|=)\s*["']?\s*([^"'<>]{6,40})/i;
const pageDate = (url, html, gdate) => {
  const h = String(html || '').slice(0, 400000);
  const meta = h.match(META) || h.match(/<time[^>]+datetime=["']([^"']+)/i);
  const um = String(url || '').match(/\/(20\d\d)[\/-](\d{1,2})[\/-](\d{1,2})(?:[\/-]|$)/);
  const hit = [[meta ? dateIn(meta[1]) : '', 'page'], [um ? iso(um[1], um[2], um[3]) : '', 'address'], [dateIn(gdate, true), 'google']].find(t => t[0]);
  return hit ? { published: hit[0], date_from: hit[1] } : { published: '', date_from: '' };
};
const toText = (html) => String(html || '')
  .replace(/<script[\s\S]*?<\/script>/gi, ' ').replace(/<style[\s\S]*?<\/style>/gi, ' ').replace(/<noscript[\s\S]*?<\/noscript>/gi, ' ')
  .replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&quot;/g, '"').replace(/&#39;/g, "'")
  .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/\s+/g, ' ').trim();
// Pairs each candidate with its page, keeps the part about the story, and writes what the update writer reads.
const story = $('Read Story From Archive').first().json;
const q = $('Store Settings').first().json;
const cands = $('Build Candidates').all().map(i => i.json);
const x = story.explainer || {};
const words = [...new Set(String(story.claim + ' ' + story.title + ' ' + (story.search_terms || '')).toLowerCase().match(/[a-z0-9][a-z0-9.\-]{2,}/g) || [])];
const windowOf = (t) => { if (t.length <= 3000) return t; const low = t.toLowerCase(); let best = 0, bs = -1;
  for (let i = 0; i < low.length - 3000; i += 500) { const w = low.slice(i, i + 3000); const sc = words.reduce((a, k) => a + (w.includes(k) ? 1 : 0), 0); if (sc > bs) { bs = sc; best = i; } }
  return t.slice(best, best + 3000); };
const esc = (t) => String(t || '').replace(/</g, '(').replace(/>/g, ')');
const pages = $input.all().map((it, i) => { const c = cands[i] || {}; const code = Number(it.json.statusCode || 0);
  const raw = String(it.json.body || ''); const d = pageDate(c.url, raw, c.gdate);
  const text = toText(raw).replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F�]/g, ' ').replace(/\s+/g, ' ').trim();
  return { n: i + 1, url: c.url, domain: c.domain, published: d.published, read: !!c.url && code >= 200 && code < 300 && text.length > 400, text }; });
const readable = pages.filter(p => p.read);
const known = (x.status_points || []).map(p => '- ' + p.status + ': ' + p.point).join('\n');
const writer_input = `<story>${esc(story.title)}. ${esc(story.claim)}</story>\n<label>${story.label}</label>\n<published_after>${story.since}</published_after>\n<question>${esc(q.question || x.open_question || '')}</question>\n<known_points>\n${known || '(none)'}\n</known_points>\n<pages>\n${readable.map(p => `<page n="${p.n}" url="${p.url}" date="${p.published || 'unknown'}">${esc(windowOf(p.text))}</page>`).join('\n') || '(no readable page)'}\n</pages>`;
return [{ json: { writer_input, pages: pages.map(({ text, ...p }) => p), readable_count: readable.length } }];

// Turns the writer's answer into the saved update and the Telegram reply. found_new needs a relevant official or reliable page (checked here, not left to the model).
const story = $('Read Story From Archive').first().json;
const q = $('Store Settings').first().json;
const bi = $('Build Writer Input').first().json;
const o = $('Write Update (via Ask Venice)').first().json.output;
const byN = Object.fromEntries((o.sources || []).map(x => [x.n, x]));
const used = bi.pages.filter(p => p.read && byN[p.n] && byN[p.n].relevant).map(p => ({ ...p, tier: byN[p.n].tier }));
const found_new = !!o.found_new && used.some(p => p.tier === 'official' || p.tier === 'reliable');
const STATUS = { confirmed: 'Confirmed', stated_only: 'Stated by the source only', not_disclosed: 'Not disclosed', contradicted: 'Contradicted' };
// Every source with its publication date.
const day = (d) => d ? new Date(d + 'T12:00:00Z').toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric', timeZone: 'UTC' }) : 'date unknown';
const dateOf = (u) => { const pg = bi.pages.find(x => x.url === u); return pg ? ', ' + day(pg.published) : ''; };
const since = new Date(story.since + 'T12:00:00Z').toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric', timeZone: 'UTC' });
const lines = found_new ? ['What changed since ' + since + ': ' + o.what_changed] : ['Nothing new from a reliable source since ' + since + '.'];
if (o.answer) lines.push('Answer: ' + o.answer);
if (found_new) for (const p of o.status_points || []) lines.push('- ' + (STATUS[p.status] || p.status) + ': ' + p.point + (p.source ? ' (' + p.source + dateOf(p.source) + ')' : ''));
const result = lines.join('\n');
const links = used.map(p => p.url + ' (' + p.tier + ', ' + day(p.published) + ')').join('\n');
const e = (t) => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const tg = ['<b>Update on #' + story.story_number + ' · ' + e(story.title) + '</b>', '', ...lines.map(e),
  ...(used.length ? ['', '<b>Sources</b>', ...used.map(p => '▫️ <a href="' + e(p.url) + '">' + e(p.domain) + '</a> (' + p.tier + ', ' + day(p.published) + ')')] : []),
  '', bi.readable_count + ' new page(s) read. Ask me anything about it here; send <code>save</code> to keep this conversation, <code>dig ' + story.story_number + '</code> for the whole story.'].join('\n');
return [{ json: { story_number: story.story_number, question: q.question || '', result, found_new, links, chat_id: String(q.chat_id), telegram_text: tg.slice(0, 4000) } }];
